        self.requirement = requirement
        self.measured = measured
        self.verdict = verdict
    }

    /// Convenience for the common numeric case.
    init(
        _ label: String,
        requirement: String,
        value: Double,
        format: String,
        passes: Bool,
        ready: Bool = true,
        pendingNote: String = "measuring…"
    ) {
        self.label = label
        self.requirement = requirement
        self.measured = String(format: format, value)
        self.verdict = ready ? (passes ? .pass : .fail) : .pending(pendingNote)
    }
}

